import{_ as t,o as e,c as a,ae as o}from"./chunks/framework.Dzr56EFm.js";const m=JSON.parse('{"title":"设计趋势 - 2026-08-05","description":"","frontmatter":{"date":"2026-08-05T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-08-05-uxtrend.md","filePath":"daily/2026-08-05-uxtrend.md"}'),n={name:"daily/2026-08-05-uxtrend.md"};function s(i,r,g,p,h,l){return e(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="设计趋势-2026-08-05" tabindex="-1">设计趋势 - 2026-08-05 <a class="header-anchor" href="#设计趋势-2026-08-05" aria-label="Permalink to &quot;设计趋势 - 2026-08-05&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势领域聚焦于AI与用户体验的融合。1. 面向代理的用户体验设计强调新型数字设备中的体验原则；2. AI工作流设计规则指出系统失败多源于设计误区；3. 人工智能时代下的用户体验2.0要求设计扩展至非人类用户；4. Figma中的AI工作流程促进创意项目实现；5. 预测2026年设计师将更多转向策略和协作。最值得关注的是AI在设计流程中的应用和设计师角色的转变。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 设计原则指导数字设备中新型用户体验</p><p><strong>能解决什么问题</strong>: 如何以人为中心设计与AI代理系统交互的体验</p><p><strong>产品应用</strong>: 适用于开发以人为本的AI代理系统，加速开发并强调人本原则</p><p><strong>示例场景</strong>: AI代理辅助团队协作和问题解决</p><hr><h3 id="_2-ai工作流设计规则" tabindex="-1">2. AI工作流设计规则 <a class="header-anchor" href="#_2-ai工作流设计规则" aria-label="Permalink to &quot;2. AI工作流设计规则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://skooloflife.medium.com/the-biggest-mistake-in-ai-workflow-design-mimicking-human-process-instead-of-optimizing-function-628bfa37aa02" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI系统失败常因设计误区，而非模型问题。</p><p><strong>能解决什么问题</strong>: 解决将AI误认为“某人”而非“某物”的设计问题。</p><p><strong>产品应用</strong>: 可应用于产品设计，直接嵌入功能而非模拟人的角色。</p><p><strong>示例场景</strong>: 自动化客服系统直接调用AI分析用户问题。</p><hr><h3 id="_3-人工智能时代下的用户体验2-0" tabindex="-1">3. 人工智能时代下的用户体验2.0 <a class="header-anchor" href="#_3-人工智能时代下的用户体验2-0" aria-label="Permalink to &quot;3. 人工智能时代下的用户体验2.0&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 在人工智能时代，用户体验设计需扩展至非人类用户。</p><p><strong>能解决什么问题</strong>: 解决非人类用户（如AI代理）的交互设计问题。</p><p><strong>产品应用</strong>: 适用于需要AI代理与人类协同工作的智能系统。</p><p><strong>示例场景</strong>: AI代理代替人类预约医生。</p><hr><h3 id="_4-figma中的ai工作流程-图像、视频与创意生成" tabindex="-1">4. Figma中的AI工作流程：图像、视频与创意生成 <a class="header-anchor" href="#_4-figma中的ai工作流程-图像、视频与创意生成" aria-label="Permalink to &quot;4. Figma中的AI工作流程：图像、视频与创意生成&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/community/ai-workflows" target="_blank" rel="noreferrer">AI Workflows for Image, Video &amp; Creative Generation | Figma</a></p><p><strong>一句话摘要</strong>: Figma社区提供的AI工作流程，助力创意项目从想法到输出。</p><p><strong>能解决什么问题</strong>: 解决AI工具生成内容时结果不一致和选择困难的问题。</p><p><strong>产品应用</strong>: 适用于实际产品，通过自定义工作流程快速生成图像、视频等内容。</p><p><strong>示例场景</strong>: 为营销活动定制视觉故事，提高创意效率。</p><hr><h3 id="_5-2026年设计师现状-ai提升设计质量" tabindex="-1">5. 2026年设计师现状：AI提升设计质量 <a class="header-anchor" href="#_5-2026年设计师现状-ai提升设计质量" aria-label="Permalink to &quot;5. 2026年设计师现状：AI提升设计质量&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/product-designers-are-not-being-replaced-they-are-being-sorted-6e2fb0492ed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI辅助设计提升质量，设计师角色向策略和协作转变</p><p><strong>能解决什么问题</strong>: AI辅助设计提升效率和质量，但需人工完成精细工作</p><p><strong>产品应用</strong>: 适用于产品设计，AI辅助创意，设计师专注策略和细节</p><p><strong>示例场景</strong>: 设计师利用AI生成原型，再进行人工精细化调整</p><hr><h3 id="_6-确定ai干预的关键点" tabindex="-1">6. 确定AI干预的关键点 <a class="header-anchor" href="#_6-确定ai干预的关键点" aria-label="Permalink to &quot;6. 确定AI干预的关键点&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@krithika_bala/designing-ai-assisted-workflows-871facbc694f" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI应增强而非取代人类能力</p><p><strong>能解决什么问题</strong>: 提高工作效率，减少认知负荷</p><p><strong>产品应用</strong>: 应用于企业流程，如文档处理，辅助识别、提取信息</p><p><strong>示例场景</strong>: 企业文档处理中的AI辅助</p><hr><h3 id="_7-产品设计中拥抱人工智能" tabindex="-1">7. 产品设计中拥抱人工智能 <a class="header-anchor" href="#_7-产品设计中拥抱人工智能" aria-label="Permalink to &quot;7. 产品设计中拥抱人工智能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://madhavsajikumar.medium.com/ai-revolution-in-product-design-shaping-the-future-of-user-experiences-076ebc45fed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI在产品设计中的整合是创造以用户为中心产品的根本转变。</p><p><strong>能解决什么问题</strong>: AI通过分析数据、学习用户互动和预测趋势，提升产品设计效率和用户体验。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，如电商应用通过AI分析购物模式提供个性化推荐。</p><p><strong>示例场景</strong>: 电商应用利用AI进行购物模式分析，提供个性化推荐。</p><hr><h3 id="_8-ai和大型语言模型中的代理工作流模式" tabindex="-1">8. AI和大型语言模型中的代理工作流模式 <a class="header-anchor" href="#_8-ai和大型语言模型中的代理工作流模式" aria-label="Permalink to &quot;8. AI和大型语言模型中的代理工作流模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/google-cloud/designing-cognitive-architectures-agentic-workflow-patterns-from-scratch-63baa74c54bc" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI和LLMs的快速发展带来了设计代理工作流的新挑战和机遇。</p><p><strong>能解决什么问题</strong>: 解决如何构建复杂、自适应AI系统的问题。</p><p><strong>产品应用</strong>: 可以应用于实际产品，通过模式指导AI系统开发，提升效率和适应性。</p><p><strong>示例场景</strong>: 使用自适应模式优化智能客服系统的响应效率。</p><hr><h3 id="_9-ai代理工作流程设计模式概览" tabindex="-1">9. AI代理工作流程设计模式概览 <a class="header-anchor" href="#_9-ai代理工作流程设计模式概览" aria-label="Permalink to &quot;9. AI代理工作流程设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流程设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理和执行任务。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，作为任务协调器处理不同问题。</p><p><strong>示例场景</strong>: 基于这些原则开发AI代理，处理复杂任务。</p><hr><h3 id="_10-ai用户体验模式介绍" tabindex="-1">10. AI用户体验模式介绍 <a class="header-anchor" href="#_10-ai用户体验模式介绍" aria-label="Permalink to &quot;10. AI用户体验模式介绍&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI用户体验模式旨在指导设计有效的AI交互体验。</p><p><strong>能解决什么问题</strong>: 解决传统UI设计无法适应AI交互需求的问题。</p><p><strong>产品应用</strong>: 可以应用到涉及AI的产品设计中，帮助选择和评估合适的交互模式。</p><p><strong>示例场景</strong>: 设计一款智能助手应用，使用户能更自然地表达意图。</p><hr>',75)])])}const c=t(n,[["render",s]]);export{m as __pageData,c as default};
